blocks.solutionCode:
def summarize_scores(records):
    scores = {}
    for record in records:
        if ':' not in record:
            continue
        parts = record.split(':', 1)
        name = parts[0].strip()
        score_str = parts[1].strip()
        if not name:
            continue
        try:
            score = int(score_str)
        except ValueError:
            continue
        if name not in scores:
            scores[name] = []
        scores[name].append(score)
    result = {}
    for name, score_list in scores.items():
        result[name] = sum(score_list) / len(score_list)
    return result

