        await queue.put(i)
        await asyncio.sleep(0.02)

async def main():
    queue = asyncio.Queue(maxsize=50)
    async with asyncio.TaskGroup() as tg:
        tg.create_task(producer(queue))
        for i in range(3):
            tg.create_task(worker(queue, i + 1))

if __name__ == '__main__':
