def max_subarray_sum(nums, k):
    if len(nums) < k or k <= 0:
        return 0
    curr = sum(nums[:k])
    max_s = curr
    for i in range(k, len(nums)):
        curr += nums[i] - nums[i - k]
        if curr > max_s:
            max_s = curr
