import heapq

def top_k_frequent(nums, k):
    freq = {}
    for num in nums:
        freq[num] = freq.get(num, 0) + 1
    heap = []
    for num, count in freq.items():
        entry = (count, -num)
        if len(heap) < k:
            heapq.heappush(heap, entry)
        elif entry < heap[0]:
            heapq.heapreplace(heap, entry)
    result = sorted([(-num) for count, num in heap], reverse=True)
    return result

# Example
