def find_hamiltonian_cycles(graph):
    n = len(graph)
    cycles = []
    def is_valid(v, pos, path):
        if not graph[path[pos - 1]][v]:
            return False
        if v in path:
            return False
        return True

    def backtrack(path, pos):
        if pos == n + 1:
            if graph[path[-1]][path[0]]:
                cycles.append(path[:])
            return
        for v in range(n):
            if is_valid(v, pos, path):
                path.append(v)
                backtrack(path, pos + 1)
                path.pop()

    for start in range(n):
        backtrack([start], 2)
    return cycles

