def almost_sorted(arr):
    n = len(arr)
    if n <= 1:
        return True
    sorted_arr = sorted(arr)
    mismatches = []
    for i in range(n):
        if arr[i] != sorted_arr[i]:
            mismatches.append(i)
    if len(mismatches) == 0:
        return True
    if len(mismatches) == 2:
        i, j = mismatches
        arr[i], arr[j] = arr[j], arr[i]
        return arr == sorted_arr
    return False

