class PrefixNode:
    def __init__(self):
        self.children = {}
        self.is_end = False

class AutoComplete:
    def __init__(self):
        self.root = PrefixNode()

    def insert(self, word):
        node = self.root
        for ch in word:
            if ch not in node.children:
                node.children[ch] = PrefixNode()
            node = node.children[ch]
        node.is_end = True

    def get_suggestions(self, prefix):
        node = self.root
        for ch in prefix:
            if ch not in node.children:
                return []
            node = node.children[ch]
        results = []
        self._collect(node, prefix, results)
        return results[:5]

    def _collect(self, node, path, results):
        if len(results) >= 5:
            return
        if node.is_end:
            results.append(path)
        for ch in sorted(node.children):
            self._collect(node.children[ch], path + ch, results)

