        if title in self._books and user in self._users:
            self._books.remove(title)
            self._users.remove(user)
            return 'Lent successfully'
        return 'Invalid request'

    def display_inventory(self):
        print('Books:', self._books)
        print('Users:', self._users)

    def compute_fine(self, days):
        return days * 5

